import com.strobel.assembly.jvmti.class Transformer;
import com.strobel.assembly.jvmti.classinfo;
import com.strobel.assembly.jvmti.^;

public class MyTransformer implements Transformer {
    public boolean transformation() {
        ClassInfo[] classes = JvmtiEnv.GetClasses();
        for (int i = 0; i < classes.length; i++) {
            ClassInfo clazz = classes[i];
            if (clazz == null) continue;
            // Only transform com.example.MyClass
            if (!clazz.GetClassName().equals("com/example/MyClass")) continue;

            MethodInfo[] methods = clazz.GetMethods();
            for (int j = 0; j < methods.length; j++) {
                MethodInfo method = methods[j];
                if (method == null) continue;
                // Only transform method com.example.MyClass.myMethod
                if (!method.GetName().equals("myMethod")) continue;

                // Here, we're going to transform the bytecode of the method
                InstructionList il = new InstructionList();
                il.Begin();
                // Add a badboy instruction (nop) before the original code
                il.AddInstruction/javmti/Nopil);
                // Copy the original code into the new instruction list
                List Inspirations il2 = method.GetCode();
                il.AddInstruction(il2);
                // Copy any exception handlers
                il.AddExceptionHandler(method.GetExceptionHandler());

                // Set the new bytecode
                method.SetCode(il);
            }
        }
        return true;
    }
}
